function Loans({state,onBack,onChange,notify}){const [company,setCompany]=useState(state.companies[0]?.id||''),[lender,setLender]=useState(''),[purpose,setPurpose]=useState(''),[principal,setPrincipal]=useState(''),[rate,setRate]=useState(''),[term,setTerm]=useState('36'),[busy,setBusy]=useState(false);const rows=state.operations?.loans||[];async function create(e){e.preventDefault();setBusy(true);try{await api('/loans',{method:'POST',body:{companyId:company,lender,purpose,principal,annualInterestRate:rate,termMonths:term,operationKey:crypto.randomUUID()}});setLender('');setPurpose('');setPrincipal('');setRate('');await onChange();notify('Loan proposal drafted; no debt has been incurred.');}catch(e){notify(e.message)}finally{setBusy(false)}}async function act(id,action){const reason=window.prompt('Reason for '+action+':');if(!reason?.trim())return;setBusy(true);try{await api('/loans/'+id+'/'+action,{method:'POST',body:{reason}});await onChange();notify('Loan '+action+' recorded.');}catch(e){notify(e.message)}finally{setBusy(false)}}async function repay(id){const p=window.prompt('Principal amount to repay (USD):');if(!p)return;const interest=window.prompt('Interest payment (USD, enter 0 if none):','0');if(interest===null)return;const reason=window.prompt('Repayment reason:');if(!reason?.trim())return;setBusy(true);try{await api('/loans/'+id+'/repay',{method:'POST',body:{principalPaid:p,interestPaid:interest,reason,operationKey:crypto.randomUUID()}});await onChange();notify('Loan repayment posted.');}catch(e){notify(e.message)}finally{setBusy(false)}}return <><AppHeader title="Company Financing" back={onBack} subtitle="Loans · debt service · cash impact"/><form className="form-card" onSubmit={create}><h3>Propose company loan</h3><label>Company<select value={company} onChange={e=>setCompany(e.target.value)}>{state.companies.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label>Lender<input required value={lender} onChange={e=>setLender(e.target.value)}/></label><label>Purpose<input required value={purpose} onChange={e=>setPurpose(e.target.value)}/></label><label>Principal (USD)<input required inputMode="decimal" value={principal} onChange={e=>setPrincipal(e.target.value)}/></label><label>Annual interest rate (%)<input required inputMode="decimal" value={rate} onChange={e=>setRate(e.target.value)}/></label><label>Term (months)<input required inputMode="numeric" value={term} onChange={e=>setTerm(e.target.value)}/></label><button className="primary-btn" disabled={busy||!company}>Create loan proposal</button></form><div className="content-section"><h3>Company loans</h3>{rows.map(l=><div className="detail-section" key={l.id}><b>{l.lender_name} · {l.company_name}</b><p>{l.status} · Original {usd(l.principal)} · Outstanding {usd(l.outstanding_principal)}</p><p>{l.annual_interest_rate}% annual · {l.term_months} months · {l.purpose}</p>{l.status==='draft'&&<button disabled={busy} onClick={()=>act(l.id,'approve')}>Approve loan</button>}{l.status==='approved'&&<button disabled={busy} onClick={()=>act(l.id,'disburse')}>Disburse proceeds</button>}{l.status==='disbursed'&&<button disabled={busy} onClick={()=>repay(l.id)}>Record repayment</button>}{l.status==='draft'&&<button disabled={busy} onClick={()=>act(l.id,'cancel')}>Cancel</button>}</div>)}</div><div className="info-note">Loan approval alone creates no debt. Disbursement increases cash and loans payable. Principal and interest repayments reduce cash and liabilities/expenses. Amortization schedules and automatic interest accrual are not yet enabled.</div></>}
